import { initTracking } from './tracking.js';

// Segmentos del asistente (ai.json, generado desde el Excel). Los SKUs no se usan en el cliente.
let AI;
try{ AI=await fetch('ai.json').then(r=>{ if(!r.ok) throw new Error('ai.json '+r.status); return r.json(); }); }
catch(e){ console.error('ai.json no disponible'); document.body.textContent='No se pudo cargar el asistente. Recarga la página.'; throw e; }
const $=id=>document.getElementById(id);
const norm=s=>s.normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase();

// ---------- presentación de nombres ----------
const FIX={BANO:'BAÑO',BANOS:'BAÑOS',NINO:'NIÑO',NINOS:'NIÑOS',PANOS:'PAÑOS',PANO:'PAÑO',DISENO:'DISEÑO',DISENOS:'DISEÑOS',PEQUENAS:'PEQUEÑAS',PEQUENOS:'PEQUEÑOS',TAMANOS:'TAMAÑOS',SENAL:'SEÑAL',ANO:'AÑO',ALGODON:'ALGODÓN',SINTETICOS:'SINTÉTICOS',SINTETICO:'SINTÉTICO',DECORACION:'DECORACIÓN',BASICOS:'BÁSICOS',QUIMICOS:'QUÍMICOS',ORGANIZACION:'ORGANIZACIÓN',ILUMINACION:'ILUMINACIÓN',HIGIENICO:'HIGIÉNICO',ELECTRICOS:'ELÉCTRICOS',ELECTRICAS:'ELÉCTRICAS',PLASTICOS:'PLÁSTICOS',PLASTICO:'PLÁSTICO',METALICOS:'METÁLICOS',CERAMICA:'CERÁMICA',ACCS:'ACCS.',MENSULAS:'MÉNSULAS',FERRETERIA:'FERRETERÍA',JARDIN:'JARDÍN',PLOMERIA:'PLOMERÍA',GASFITERIA:'GASFITERÍA',AUTOMOVILES:'AUTOMÓVILES',ENTRETENCION:'ENTRETENCIÓN',CAMPANA:'CAMPANA'};
const SMALL=new Set(['de','del','la','el','los','las','y','o','a','en','para','con','sin','por']);
function pretty(s){
  return s.split(/(\s+|\/|-)/).map(w=>{
    if(!/[A-Z]/.test(w)) return w;
    const f=FIX[w]||w; const l=f.toLowerCase();
    if(SMALL.has(l)) return l;
    if(/\d/.test(f)&&/X/.test(f)) return l;
    return l.charAt(0).toUpperCase()+l.slice(1);
  }).join('').replace(/^./,c=>c.toUpperCase());
}

// ---------- índice ----------



// ================= ASISTENTE DE NECESIDADES =================
const SEGS=AI.segs.map(([fam,name,n,esp],id)=>({id,fam,name,n,esp,pretty:pretty(name)}));
const A={text:'',answers:[],plan:null,ruta:null,sel:null,source:null,busy:false,rutaVista:false,svVisto:false,lastSearchId:null};
let sampleFn=null, ctl=null, timer=null;

function clean(plan){
  const p=plan&&typeof plan==='object'?plan:{};
  const grupos=(Array.isArray(p.grupos)?p.grupos:[]).map(g=>({
    rol:String(g.rol||'Necesario'),titulo:String(g.titulo||''),por_que:String(g.por_que||''),
    preferir:(Array.isArray(g.preferir)?g.preferir:[]).map(x=>norm(String(x))).filter(Boolean),
    segmentos:(Array.isArray(g.segmentos)?g.segmentos:[]).map(Number).filter(n=>Number.isInteger(n)&&n>=0&&n<SEGS.length)
  })).filter(g=>g.segmentos.length);
  // El grupo principal va primero: de él salen los destinos; los demás se muestran como "También puedes necesitar"
  const pi=grupos.findIndex(g=>/^principal/i.test(g.rol.trim()));
  if(pi>0) grupos.unshift(...grupos.splice(pi,1));
  return {necesidad:String(p.necesidad||''),proyecto:String(p.proyecto||''),espacio:String(p.espacio||''),
    contexto:(Array.isArray(p.contexto)?p.contexto:[]).map(String).slice(0,6),grupos,
    preguntas:(Array.isArray(p.preguntas)?p.preguntas:[]).filter(q=>q&&q.pregunta).slice(0,3).map(q=>({pregunta:String(q.pregunta),opciones:(Array.isArray(q.opciones)?q.opciones:[]).map(String).slice(0,4)})),
    consejo:String(p.consejo||'')};
}


function el(tag,cls,text){ const e=document.createElement(tag); if(cls) e.className=cls; if(text!=null) e.textContent=text; return e; }

// ---------- Respuesta por destino en ventana emergente: dónde está, no un SKU ----------
// Ubicaciones con prefijo P (01P…, Zona P) están en Patio Constructor: la ruta llega a la salida "patio" del plano
const esPatio=d=>d.pasillos.some(p=>/^\d+P$/i.test(p))||/Zona-P/i.test(d.id);
function rutaAisle(d){ return d.pasillos.map(x=>x.toLowerCase()).find(x=>MAPIDS.has(x))||(esPatio(d)&&MAPIDS.has('patio')?'patio':null); }
