    mapIds(x.d).forEach(m=>aisleEls(m).forEach(e=>{ const q=e.getBoundingClientRect(); if(!q.width&&!q.height) return; l=Math.min(l,q.left);t=Math.min(t,q.top);r=Math.max(r,q.right);bo=Math.max(bo,q.bottom); }));
    if(r<l){ b.style.display='none'; return; } b.style.display='';
