function styleRoute(r){
  const sv=$('mapa'), m=r.mueble;
  // La ruta puede llegar a una mitad de un pasillo partido (11b-n, 29a-e…): se pinta el pasillo completo
  const base=String(m||'').replace(/-[nsew]$/i,'');
  [...new Set([m,base])].forEach(x=>aisleEls(x).forEach(e=>e.classList.add('dest','dest-sel')));
  const j=rutaGrupo(); if(!j) return;
  const ps=j.querySelectorAll(':scope > path'); if(ps[0]) ps[0].setAttribute('stroke-width','20'); if(ps[1]) ps[1].setAttribute('stroke','#b9d7f2');
  const gs=j.querySelectorAll(':scope > g');
  if(gs[0]){ const c=gs[0].querySelectorAll('circle'); if(c[0]) c[0].setAttribute('stroke','#0072ce'); if(c[1]){ c[1].setAttribute('fill','#0072ce'); c[1].setAttribute('stroke','#ffffff'); } if(c[2]) c[2].setAttribute('fill','#ffffff'); }
  for(let i=1;i<gs.length;i++){ const rc=gs[i].querySelector('rect'); if(rc) rc.setAttribute('fill','#005ba6'); }
  j.querySelectorAll(':scope > circle').forEach(c=>c.setAttribute('fill','#005ba6'));
  j.querySelectorAll(':scope > line').forEach(l=>l.setAttribute('stroke','#005ba6'));
}
function clearDest(){ document.querySelectorAll('#mapa .dest,#mapa .dest-sel,#mapa .dest-alt').forEach(e=>e.classList.remove('dest','dest-sel','dest-alt')); clearCallouts(); }
function hideRoute(){ clearDest(); R.token++; cancelAnimationFrame(R.anim); R.guiando=false;
  // borra la ruta anterior (capa sin id al final del plano) y anula un recorrido que estuviera por arrancar
  { const j=rutaGrupo(); if(j&&!j.id) j.replaceChildren(); R.ruta=null; R.trail=null; R.marker=null; R.len=0; } $('rutaModal').classList.add('idle'); try{ const d=$('destino'); d.value=''; if(d.onchange) d.onchange(); }catch(e){} if(window.VB0) $('mapa').setAttribute('viewBox',window.VB0); document.querySelectorAll('.card.sel,.dcard.sel').forEach(c=>c.classList.remove('sel')); }
// Ruta completa de una vez (el trazo se dibuja en ~1 s, sin mover la cámara)
function openRoute(s,aisle,btn,dest){
  cancelGuide();
  document.querySelectorAll('.card.sel,.dcard.sel').forEach(c=>c.classList.remove('sel')); btn?.closest('.card,.dcard')?.classList.add('sel');
  $('rutaTitulo').textContent=dest&&dest.lugar?'Cómo llegar al '+dest.lugar.toLowerCase()+' '+dest.rango:dest&&dest.pasillos.length>1?'Cómo llegar a los pasillos '+dest.rango:'Cómo llegar al pasillo '+aisle.toUpperCase();
  $('rutaProducto').textContent=s.d+(s.sku?' · SKU '+s.sku:'');
  window.ultimaRuta=null; R.marker=null; R.trail=null; R.len=0; R.paso=-1;
  clearDest();
  const sel=$('destino'); sel.value=aisle; $('desde').value=''; if(sel.onchange) sel.onchange();
  const r=window.ultimaRuta, ol=$('rutaPasos'); ol.innerHTML=''; caption('');
  if(!r||r.destino!==aisle){
    R.ruta=null; ol.appendChild(el('li',null,'No pudimos trazar la ruta a este pasillo. Pide ayuda a un asesor de la tienda.'));
    $('rutaProg').textContent=''; ['rutaPlay','rutaPrev','rutaNext'].forEach(id=>$(id).disabled=true);
  } else {
    R.ruta=r; R.fit=STORE.slice(); setVB(R.fit); styleRoute(r);
    if(dest) paint(dest.pasillos.map(x=>x.toLowerCase()).filter(x=>MAPIDS.has(x)&&x!==aisle),'dest');
    R.pasos=['Empiezas en la entrada principal.',...r.instrucciones];
    R.dist=[0,...(r.tramos||[]).slice(0,r.instrucciones.length)];
    while(R.dist.length<R.pasos.length) R.dist.push(r.largo);
    R.pasos.forEach((t,i)=>{ const li=el('li',null,t); li.onclick=()=>goStep(i); ol.appendChild(li); });
    $('rutaPlay').disabled=false;
  }
  if(R.ruta) setTimeout(()=>{ if(R.ruta===r) guided(); },120);
  $('rutaModal').scrollIntoView({behavior:REDUCE?'auto':'smooth',block:'nearest'});
}
$('rutaCerrar').onclick=()=>{ const b=document.querySelector('.sel .go'); hideRoute(); if(b) b.focus(); };
$('rutaPlay').onclick=()=>{ if(R.guiando){ cancelGuide(); place(R.L); setPaso(R.pasos.length-1); } else guided(); };
$('rutaPrev').onclick=()=>goStep(R.paso-1);
$('rutaNext').onclick=()=>goStep(R.paso+1);
$('verTodo').addEventListener('click',()=>cancelGuide(true));
$('mapa').addEventListener('pointerdown',()=>{ if(R.guiando) cancelGuide(); });
$('mapa').addEventListener('wheel',()=>{ if(R.guiando) cancelGuide(); },{passive:true});

// Mensaje de error con botón "Reintentar" (la consulta vuelve a salir con el mismo texto)
function setError(msg){ setStatus(msg,true); const s=$('aiStatus'); const b=document.createElement('button'); b.type='button'; b.className='retry'; b.textContent='Reintentar'; b.onclick=()=>{ if(!A.busy) ask(); }; s.append(' ',b); }
function setStatus(msg,err,busy){ const s=$('aiStatus'); s.className='status'+(err?' err':'')+(busy?' busy':''); if(busy){ s.innerHTML='<span class="dots" aria-hidden="true"><i></i><i></i><i></i></span><span class="think-txt"></span>'; s.querySelector('.think-txt').textContent=msg; } else s.textContent=msg; const b=document.querySelector('.askbox'); if(b) b.classList.toggle('thinking',!!busy); }
const THINK=['Pensando…','Entendiendo tu necesidad…','Buscando en el catálogo de la tienda…','Eligiendo los productos ideales…','Armando tu ruta en la tienda…'];
const SUGERIR=' También puedes escribir solo el producto, por ejemplo «pintura», «llave» o «tapete».';
const ERR={ia_ocupada:'El asistente está muy ocupado en este momento y no pudo responder.'+SUGERIR,error:'El asistente no pudo responder esta vez.'+SUGERIR,network:'No hay conexión con el asistente. Revisa tu internet e intenta de nuevo.',timeout:'El asistente tardó demasiado en responder.'+SUGERIR,not_granted:'La IA no tiene permiso en esta vista. Acepta el permiso para usar Claude cuando la página lo pida.',sampling_disabled:'La IA no está disponible para esta cuenta.',rate_limited:'Demasiadas consultas seguidas. Espera un momento y vuelve a intentar.',invalid_json:'La respuesta no llegó en el formato esperado. Intenta de nuevo.',refused:'La IA no pudo responder a esa solicitud. Prueba a describirla de otra forma.',session_expired:'Tu sesión expiró. Vuelve a iniciar sesión.'};

async function ask(){
  const text=A.text.trim(); if(!text) { setStatus('Escribe primero qué necesitas.',true); return; }
  if(!sampleFn){ setStatus('La búsqueda con IA no está disponible en este momento.',true); return; }
  A.busy=true; $('askBtn').disabled=true; $('stopBtn').hidden=false;
  if(window.gtag) gtag('event','search_submit',{canal:window.__canalBusqueda||'texto'});
  hideSurvey(); A.lastSearchId=null; // un aviso viejo nunca puede responder a otra búsqueda
  hideRoute(); hint(''); // búsqueda nueva: fuera la ruta y las etiquetas de la anterior
  const t0=Date.now(); let ti=0; setStatus(THINK[0],false,true);
  timer=setInterval(()=>{ ti=Math.min(ti+1,THINK.length-1); const tx=document.querySelector('#aiStatus .think-txt'); if(tx) tx.textContent=THINK[ti]; },2600);
  ctl=new AbortController();
  try{
    let j;
    try{ j=await sampleFn.json({signal:ctl.signal}); }
    catch(e){
      // un reintento automático si la IA estuvo ocupada, falló o se cortó la conexión (no si el cliente la detuvo)
      if(!e||e.code!=='network') throw e;
      clearInterval(timer); setStatus(e.code==='network'?'Reconectando con el asistente…':'El asistente está ocupado, lo intentamos de nuevo…',false,true);
      await new Promise((ok,no)=>{ const t=setTimeout(ok,1500); ctl.signal.addEventListener('abort',()=>{ clearTimeout(t); no({code:'cancelled'}); },{once:true}); });
      j=await sampleFn.json({signal:ctl.signal});
    }
    A.plan=j.plan?clean(j.plan):null; A.ruta=j.ruta||null; A.sel=null; A.source=A.ruta&&A.ruta.fuente==='indice'?'indice':'ai'; A.rutaVista=false; A.svVisto=false; A.lastSearchId=j.id||null; renderPlan();
    const ok=(A.ruta&&A.ruta.destinos&&A.ruta.destinos.length)||(A.plan&&A.plan.grupos.length);
    const dt=Date.now()-t0;
    if(window.gtag) gtag('event','search_result',{resultado:A.ruta&&A.ruta.respaldo?'respaldo':(A.ruta&&A.ruta.fuente==='indice'?'indice':'modelo'),canal:window.__canalBusqueda||'texto',ms:dt});
    // UX-07: el resultado se explica en la línea bajo el mapa; si respondió el índice porque la IA no pudo, se avisa
    if(ok&&A.ruta&&A.ruta.respaldo) setStatus('El asistente no pudo armar recomendaciones ahora; te mostramos dónde está «'+(A.ruta.consulta||text)+'».');
    else setStatus(ok?'':'No encontramos productos de la tienda para esta necesidad.');
    // con respuesta recibida se limpia solo el input de texto (si no se escribió otra cosa mientras tanto)
    { const n=$('need'); if(n.value.trim()===text) n.value=''; }
  }catch(e){
    if(e&&e.code==='cancelled') setStatus('Consulta detenida.');
    else {
      if(window.gtag) gtag('event','search_result',{resultado:'error',canal:window.__canalBusqueda||'texto',ms:Date.now()-t0}); const m=ERR[e&&e.code]||'No se pudo completar la consulta.'+SUGERIR; if(e&&(e.code==='not_granted'||e.code==='sampling_disabled')){ setStatus(m,true); sampleFn=null; } else setError(m); }
  }finally{ clearInterval(timer); A.busy=false; $('askBtn').disabled=false; $('stopBtn').hidden=true; }
}
// Canal de la búsqueda para el registro: 'voz' solo si este clic lo disparó el dictado (submit() del micrófono
// marca __vozPendiente durante su click() síncrono); clics, Enter y todo lo demás son 'texto'.
$('askBtn').onclick=()=>{ window.__canalBusqueda=window.__vozPendiente?'voz':'texto'; const v=$('need').value; if(v.trim()!==A.text.trim()) A.answers=[]; A.text=v; ask(); };
$('need').addEventListener('keydown',e=>{ if(e.key==='Enter'&&!e.shiftKey){ e.preventDefault(); $('askBtn').click(); } });
/* MIC-JS */
(function(){
  let hT=null; const hd=()=>$('heard');
  function hideHeard(){ clearTimeout(hT); const h=hd(); if(h){ h.hidden=true; h.textContent=''; } }
  function showHeard(q){ const h=hd(); if(!h) return; clearTimeout(hT); h.textContent='Buscaste: «'+q+'»'; h.hidden=false; hT=setTimeout(hideHeard,10000); }
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition, btn=$('micBtn'), box=$('need'), ab=document.querySelector('.askbox');
  if(!SR||!btn) return;
  btn.hidden=false;
  // fin: 'auto' (toque: busca al callar) | 'hold' (presionado: busca al soltar) | 'stop' (deja el texto) | 'buscar' | 'cancel'
  let rec=null, base='', heard=false, fin='auto';
  const sep=t=>t&&!/\s$/.test(t)?' ':'';
  const on=v=>{ ab.classList.toggle('listening',v); btn.classList.toggle('rec',v); btn.setAttribute('aria-pressed',String(v)); };
  const listening=()=>ab.classList.contains('listening');

  // Onda de voz: historial de volumen real del micrófono que se desplaza a la izquierda.
  // Si no hay acceso al audio en paralelo, onda sintética que sube cuando llega texto reconocido.
  const wv=document.querySelector('.wave'), bars=wv?[...wv.children]:[];
  const M={ctx:null,stream:null,an:null,buf:null,raf:0,lvl:0,hist:[],voz:0};
  function mStart(real){
    if(!wv) return; mStop(); M.hist=bars.map(()=>0); M.lvl=0; M.voz=0; M.snd=false;
    if(real) try{ const AC=window.AudioContext||window.webkitAudioContext; if(AC){ M.ctx=new AC(); M.ctx.resume&&M.ctx.resume(); } }catch(e){ M.ctx=null; }
    if(real&&M.ctx&&navigator.mediaDevices&&navigator.mediaDevices.getUserMedia){
      navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}}).then(st=>{
        if(!listening()||!M.ctx){ st.getTracks().forEach(t=>t.stop()); return; }
        M.stream=st; const src=M.ctx.createMediaStreamSource(st); M.an=M.ctx.createAnalyser(); M.an.fftSize=512; M.an.smoothingTimeConstant=.3;
        M.buf=new Uint8Array(M.an.fftSize); src.connect(M.an);
      }).catch(()=>{});
    }
    const tick=()=>{ const t=performance.now();
      let v;
      if(M.an){ M.an.getByteTimeDomainData(M.buf); let q=0; for(let k=0;k<M.buf.length;k++){ const d=(M.buf[k]-128)/128; q+=d*d; } const rms=Math.sqrt(q/M.buf.length); v=Math.min(1,Math.max(0,(Math.sqrt(rms)-.08)*1.9)); }
      else { const hab=t-M.voz<500; v=hab?.35+Math.random()*.6:(M.snd?.08+Math.random()*.22:Math.random()*.06); }
      M.lvl=v>M.lvl?v:M.lvl*.6+v*.4;
      M.hist.push(M.lvl); M.hist.shift();
      bars.forEach((b,k)=>{ b.style.transform='scaleY('+(.12+M.hist[k]*.88).toFixed(3)+')'; });
      wv.classList.toggle('voz',M.lvl>.18);
    };
    M.raf=setInterval(tick,80);
  }
  function mStop(){
    clearInterval(M.raf); M.raf=0; M.an=null;
    if(M.stream){ M.stream.getTracks().forEach(t=>t.stop()); M.stream=null; }
    if(M.ctx){ try{ M.ctx.close(); }catch(e){} M.ctx=null; }
    bars.forEach(b=>{ b.style.transform=''; }); wv&&wv.classList.remove('voz');
  }
  // click() es síncrono: onclick lee __vozPendiente y luego se limpia aunque el botón estuviera deshabilitado y no corriera
  function submit(){ const q=box.value.trim(); if(!q) return; window.__vozPendiente=true; try{ $('askBtn').click(); }finally{ window.__vozPendiente=false; } box.value=''; showHeard(q); }
  // Modos: toque = escucha hasta que la persona calla y envía solo ('auto').
  //        mantener presionado = escucha mientras el dedo esté abajo; al soltar envía ('hold'); deslizar a la izquierda cancela.
  let holding=false, holdT=0, x0=0, out=false, fine=false, done=true, guardT=0;
  let t0=0, restarts=0, fatal=false, retryOnUp=false, retried=false, ghostUntil=0;
  const CANCEL_PX=80, HOLD_MS=350, WAIT_MS=8000, MAX_RESTARTS=6, GHOST_MS=600;
  // Diagnóstico en el teléfono: abrir la página con ?debugmic=1 muestra los eventos del dictado
  const DBG=/[?&]debugmic=1/.test(location.search); let dbgEl=null;
  function log(m){ if(!DBG) return; if(!dbgEl){ dbgEl=document.createElement('pre'); dbgEl.style.cssText='position:fixed;left:8px;right:8px;top:8px;z-index:99;max-height:38vh;overflow:auto;margin:0;padding:8px;background:rgba(0,0,0,.82);color:#9fe870;font:11px/1.35 monospace;border-radius:8px;white-space:pre-wrap;pointer-events:none'; document.body.appendChild(dbgEl); }
    const t=t0?((performance.now()-t0)/1000).toFixed(2)+'s ':''; dbgEl.textContent=(t+m+'\n'+dbgEl.textContent).slice(0,4000); }
  function session(){
    rec=new SR(); rec.lang='es-CO'; rec.interimResults=true; rec.continuous=false; rec.maxAlternatives=1;
    rec.onaudiostart=()=>log('audiostart');
    rec.onsoundstart=()=>{ M.snd=true; log('soundstart'); }; rec.onspeechstart=()=>{ M.snd=true; M.voz=performance.now(); log('speechstart'); }; rec.onsoundend=()=>{ M.snd=false; };
    const pre=box.value;
    rec.onresult=e=>{
      let t='';
      for(let i=0;i<e.results.length;i++) t+=e.results[i][0].transcript;
      t=t.trim(); if(t){ heard=true; box.value=pre+sep(pre)+t; }
      M.voz=performance.now(); log('result: '+t);
    };
    rec.onerror=e=>{ log('error: '+e.error);
      if(e.error==='audio-capture'){ if(M.stream){ mStop(); } else fatal=true; }
      if(e.error==='network') fatal=true;
      if(e.error==='not-allowed'||e.error==='service-not-allowed'){
        // iOS: iniciar en pointerdown táctil no siempre cuenta como gesto; reintentamos al levantar el dedo
        if(holding&&!fine&&!retried){ retryOnUp=true; fin='retry'; }
        else { fin='cancel'; fatal=true; holding=false; setStatus('Permite el acceso al micrófono para dictar.',true); }
      } };
    const me=rec;
    rec.onend=()=>{
      log('end');
      if(me!==rec||done) return;
      // Manteniendo presionado: si el navegador corta por una pausa, seguimos escuchando
      if(fin==='hold'&&holding){ try{ log('restart (hold)'); session(); return; }catch(e){} }
      // Toque: si el navegador corta antes de que la persona empiece a hablar, seguimos esperando hasta WAIT_MS
      if(fin==='auto'&&!heard&&!fatal&&restarts<MAX_RESTARTS&&performance.now()-t0<WAIT_MS){ restarts++; try{ log('restart (esperando voz)'); session(); return; }catch(e){} }
      finish();
    };
    rec.start(); log('start');
  }
  function finish(){
      if(done) return; done=true; clearTimeout(guardT);
      ab.classList.remove('hold','out','pressing'); on(false); mStop();
      log('finish: '+fin+(heard?' (con texto)':' (sin texto)'));
      if(fin==='retry'){ box.value=base; return; }
      if(fin==='cancel'){ box.value=base; return; }
      if(fin==='buscar'||((fin==='auto'||fin==='hold')&&heard)) submit();
      else if(fin==='auto'&&!fatal) setStatus('No te escuchamos. Toca el micrófono e intenta de nuevo.');
      // Solo con mouse/teclado: en táctil el teclado se abre únicamente si la persona toca el campo
      else if(fin==='stop'&&fine){ try{ box.focus(); box.setSelectionRange(box.value.length,box.value.length); }catch(e){} }
  }
  function start(focus){
    if(box.value.trim()===A.text.trim()) box.value=''; base=box.value; heard=false; fin='auto'; done=false; clearTimeout(guardT); hideHeard();
    t0=performance.now(); restarts=0; fatal=false; retryOnUp=false;
    on(true); mStart(fine);
    if(focus&&fine){ try{ box.focus({preventScroll:true}); }catch(e){} }
    try{ session(); }catch(e){ log('start falló: '+(e&&e.name));
      if(holding&&!fine&&!retried){ retryOnUp=true; fin='retry'; finish(); }
      else { fin='cancel'; fatal=true; finish(); setStatus('No se pudo activar el micrófono en este navegador.',true); } }
  }
  const end=f=>{ if(done) return; log('end('+f+')'); fin=f; holding=false; ab.classList.remove('hold','out','pressing'); clearTimeout(guardT); guardT=setTimeout(finish,1200);
    try{ f==='cancel'?rec.abort():rec.stop(); }catch(e){ finish(); } };
  const hint=ab.querySelector('.hold-hint');
  btn.addEventListener('contextmenu',e=>e.preventDefault());
  btn.addEventListener('pointerdown',e=>{
    if(e.button!==0||listening()) return;
    e.preventDefault(); fine=e.pointerType==='mouse'; retried=false;
    try{ btn.setPointerCapture(e.pointerId); }catch(_){}
    holding=true; out=false; x0=e.clientX; ab.classList.add('pressing');
    if(!fine) ghostUntil=Infinity; // bloquea clics fantasma hasta GHOST_MS después de levantar el dedo
    start(false);
    clearTimeout(holdT);
    holdT=setTimeout(()=>{
      if(!holding||!listening()) return;
      fin='hold'; ab.classList.add('hold'); if(navigator.vibrate) navigator.vibrate(15);
    },HOLD_MS);
  });
  btn.addEventListener('pointermove',e=>{
    if(!holding||!ab.classList.contains('hold')) return;
    const dx=Math.min(0,e.clientX-x0); out=dx<-CANCEL_PX;
    ab.classList.toggle('out',out);
    if(hint){ hint.style.transform='translateX('+Math.max(dx,-CANCEL_PX)/2+'px)'; hint.style.opacity=String(1-Math.min(1,-dx/CANCEL_PX)*.5); }
  });
  function release(cancelled,e){
    clearTimeout(holdT);
    if(e&&e.pointerType!=='mouse') ghostUntil=performance.now()+GHOST_MS;
    if(hint){ hint.style.transform=''; hint.style.opacity=''; }
    if(!holding){ ab.classList.remove('pressing');
      if(retryOnUp&&!cancelled){ retryOnUp=false; retried=true; log('reintento al soltar'); start(false); }
      return; }
    const wasHold=ab.classList.contains('hold');
    holding=false; ab.classList.remove('pressing');
    if(retryOnUp&&!cancelled){ retryOnUp=false; retried=true; log('reintento al soltar'); if(!done){ fin='retry'; finish(); } start(false); return; }
    if(!wasHold){ // toque corto: sigue escuchando hasta que la persona calle
      if(fine){ try{ box.focus({preventScroll:true}); }catch(_){} }
      return;
    }
    end(cancelled||out?'cancel':'buscar');
  }
  btn.addEventListener('pointerup',e=>release(false,e));
  btn.addEventListener('pointercancel',e=>{ log('pointercancel'); release(true,e); });
  // Clic fantasma: tras un toque, los móviles disparan un click en el punto del dedo. Como el micrófono
  // desaparece y en su lugar queda "Detener", ese click detenía el dictado y abría el teclado. Se descarta.
  const ghost=e=>{ if(e.isTrusted&&performance.now()<ghostUntil&&!e.target.closest('#micBtn')){ e.preventDefault(); e.stopPropagation(); log('clic fantasma bloqueado ('+e.type+')'); } };
  document.addEventListener('click',ghost,true);
  document.addEventListener('mousedown',ghost,true);
  box.addEventListener('focus',()=>{ if(performance.now()<ghostUntil){ box.blur(); log('foco fantasma bloqueado'); } });
  // Teclado (Enter/Espacio): mismo comportamiento que un toque
  btn.addEventListener('click',e=>{ if(e.detail!==0) return; if(listening()) end('stop'); else { fine=true; start(true); } });
  $('micStop').onclick=()=>end('stop');
  $('micCancel').onclick=()=>end('cancel');
  // "Buscar" mientras escucha: cierra el dictado y busca con lo dictado
  ab.addEventListener('click',e=>{ if(listening()&&e.target.closest('#askBtn')){ e.stopPropagation(); end('buscar'); } },true);
  document.addEventListener('keydown',e=>{ if(e.key==='Escape'&&listening()) end('cancel'); });
})();
/* /MIC-JS */
$('stopBtn').onclick=()=>ctl&&ctl.abort();
// Despliegue en Vercel: la IA se consulta en /api/sample (la clave de Anthropic vive en el servidor)
sampleFn={ async json(opts){
  // límite de 55 s por consulta (la función del servidor corta a los 60 s)
  const lim=new AbortController(), tl=setTimeout(()=>lim.abort(),55000), sg=opts&&opts.signal; if(sg) sg.addEventListener('abort',()=>lim.abort(),{once:true});
  let r; try{ r=await fetch('/api/sample',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:A.text,answers:A.answers,canal:window.__canalBusqueda||'texto'}),signal:lim.signal}); }
  catch(e){ throw {code:(sg&&sg.aborted)?'cancelled':(e&&e.name==='AbortError')?'timeout':'network'}; }
  finally{ clearTimeout(tl); }
  let j=null; try{ j=await r.json(); }catch(e){}
  if(!r.ok||!j||j.error) throw {code:(j&&j.error)||(r.status===429?'rate_limited':r.status===503?'ia_ocupada':'error')};
  return j;
} };
